def polynomial_to_string(n: int, coeffs: list[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.

    Raises:
        TypeError: If n is not an int or coeffs is not a list of ints.
        ValueError: If n is negative or the length of coeffs does not match n+1.
    """
    # Validate inputs
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    if not isinstance(coeffs, list):
        raise TypeError("coeffs must be a list")
    if len(coeffs) != n + 1:
        raise ValueError(f"coeffs length must be {n + 1}")
    for c in coeffs:
        if not isinstance(c, int):
            raise TypeError("All coefficients must be integers")

    terms = []
    first_term = True

    for degree, coeff in enumerate(range(n, -1, -1)):
        c = coeffs[n - degree]  # coeffs are ordered from highest degree to constant
        if c == 0:
            continue

        # Determine sign
        if first_term:
            sign = '-' if c < 0 else ''
        else:
            sign = '-' if c < 0 else '+'

        abs_c = abs(c)

        # Determine variable part
        if degree == 0:
            var = ''
        elif degree == 1:
            var = 'x'
        else:
            var = f'x^{degree}'

        # Determine coefficient part
        if abs_c == 1 and degree > 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_c)

        term = f"{sign}{coeff_str}{var}"
        terms.append(term)
        first_term = False

    if not terms:
        return '0'
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    # Basic validation: lengths must match
    if len(encoded) != len(original):
        return "Failed"

    # Ensure all characters are uppercase letters
    if not (encoded.isalpha() and original.isalpha() and message.isalpha()):
        return "Failed"

    enc_to_orig = {}
    orig_to_enc = {}

    for e, o in zip(encoded, original):
        # Check consistency for encoded -> original
        if e in enc_to_orig:
            if enc_to_orig[e] != o:
                return "Failed"
        else:
            enc_to_orig[e] = o

        # Check consistency for original -> encoded (bijection)
        if o in orig_to_enc:
            if orig_to_enc[o] != e:
                return "Failed"
        else:
            orig_to_enc[o] = e

    # All 26 letters must be represented in the mapping
    if len(enc_to_orig) != 26:
        return "Failed"

    # Decode the message
    decoded_chars = []
    for ch in message:
        if ch not in enc_to_orig:
            return "Failed"
        decoded_chars.append(enc_to_orig[ch])

    return "".join(decoded_chars)

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to 10 steps. Returns minimum steps or "NO ANSWER!" if impossible.
    """
    # Basic validation
    if not isinstance(A, str) or not isinstance(B, str) or not isinstance(rules, list):
        raise TypeError("Invalid input types.")
    # If already equal
    if A == B:
        return 0
    # Filter out rules with empty source to avoid infinite loops
    valid_rules = [(src, tgt) for src, tgt in rules if isinstance(src, str) and isinstance(tgt, str) and src]
    # BFS initialization
    queue = [(A, 0)]
    visited = {A}
    max_steps = 10
    while queue:
        current, steps = queue.pop(0)
        if steps >= max_steps:
            continue
        next_step = steps + 1
        for src, tgt in valid_rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return next_step
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, next_step))
                start = idx + 1  # allow overlapping matches
    return "NO ANSWER!"

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Basic type validation
    if not isinstance(scenario, str):
        raise TypeError("scenario must be a string")
    if not isinstance(liar_count, set):
        raise TypeError("liar_count must be a set")
    if not isinstance(statements, dict):
        raise TypeError("statements must be a dict")
    if not isinstance(days_of_week, set):
        raise TypeError("days_of_week must be a set")

    def _evaluate(statement: str, speaker: str) -> bool:
        """
        Evaluate the truth value of a single statement given the speaker and the scenario.
        """
        if not isinstance(statement, str):
            # Non-string statements are considered invalid; treat as False
            return False
        stmt = statement.strip()
        # Ignore statements about the day of the week
        for day in days_of_week:
            if day in stmt:
                return None  # signal to ignore
        # Remove trailing period if present
        if stmt.endswith('.'):
            stmt = stmt[:-1]
        lower = stmt.lower()
        if lower == "i am guilty":
            return speaker == scenario
        if lower == "i am not guilty":
            return speaker != scenario
        parts = stmt.split()
        if len(parts) >= 3 and parts[1] == "is":
            name = parts[0]
            if parts[2] == "guilty":
                return name == scenario
            if parts[2] == "not" and len(parts) >= 4 and parts[3] == "guilty":
                return name != scenario
        # If the statement cannot be parsed, treat it as False
        return False

    for speaker, stmts in statements.items():
        if not isinstance(speaker, str):
            raise TypeError("Participant names must be strings")
        if not isinstance(stmts, list):
            raise TypeError("Statements for each participant must be a list")
        for stmt in stmts:
            truth = _evaluate(stmt, speaker)
            if truth is None:
                # Statement about day of week; ignore
                continue
            if speaker in liar_count:
                if truth:
                    return False  # liar told a true statement
            else:
                if not truth:
                    return False  # truth-teller told a false statement
    return True

